import{useEffect,useState,type FormEvent}from'react';
import{ArrowRight,BarChart3,BookOpen,Building2,Check,ChevronRight,Clock3,CreditCard,Database,ExternalLink,Gift,LoaderCircle,LockKeyhole,MapPin,Megaphone,Menu,Plug,ReceiptText,Search,ShieldCheck,ShoppingBag,Sparkles,Users,X}from'lucide-react';
import{api}from'./api';import{BrandLogo}from'./BrandLogo';import{LegalFooter}from'./LegalPages';import'./public-site.css';
import'./trial-signup.css';
import'./public-site-evolution.css';

type Plan={code:string;name:string;tagline:string;monthlyPriceCents:number;userLimit:number;consumerLimit:number;storageMb:number;storageGb:number;features:string[];highlight?:boolean;trialDays:number};
const labels:Record<string,string>={core_crm:'CRM e gestão de clientes',loyalty:'Fidelidade e pontos',rewards:'Catálogo de recompensas',customer_portal:'Aplicativo do cliente',erp_integrations:'Integrações ERP disponíveis',basic_reports:'Relatórios básicos',campaigns_basic:'Campanhas segmentadas',operational_dashboard:'Dashboard operacional',offers:'Ofertas exclusivas no app',manager_dashboard:'Dashboard gerencial',campaigns_advanced:'Testes A/B e atribuição',gie:'Inteligência GIE',public_api:'API pública',advanced_reports:'Relatórios avançados',automations:'Automações de relacionamento',priority_support:'Suporte prioritário',multi_unit:'Gestão multiunidade',audit_export:'Auditoria e exportação'};
const money=(cents:number)=>(cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
type FaqItem={q:string;a:string};
type FaqCategory={title:string;items:FaqItem[]};
const supportFaq:FaqCategory[]=[
 {title:'Começar e contratar',items:[
  {q:'O que é o Fidelizei?',a:'É uma plataforma de fidelidade para empresas que reúne cadastro de clientes, regras de pontos, recompensas, ofertas, campanhas e integração com sistemas de venda. A disponibilidade de cada recurso depende do plano e da configuração da loja.'},
  {q:'Como funciona o teste grátis de 7 dias?',a:'O teste começa quando o ambiente é ativado. A tela de adesão informa o plano e o preço integral que poderá ser cobrado após o período; nenhuma cobrança ocorre durante os 7 dias. Para evitar a cobrança futura, cancele antes do fim do teste, conforme as condições exibidas na contratação.'},
  {q:'Posso mudar ou cancelar meu plano?',a:'O responsável da empresa pode solicitar a mudança pelo portal. Limites e recursos passam a seguir o plano efetivamente ativo. Consulte a tela de assinatura para conferir preço, vigência, forma de pagamento e confirmação da mudança.'},
  {q:'O que preciso preparar antes de divulgar o programa?',a:'Revise os dados e a logo da loja, regras de pontuação, validade e resgate, níveis de clientes, políticas de privacidade, canais de atendimento e integração com o ERP. Faça uma compra teste, confira os pontos e teste um cancelamento antes de convidar clientes.'}
 ]},
 {title:'Clientes, vendas e pontos',items:[
  {q:'Como uma venda gera pontos?',a:'A loja define a regra de pontuação. O pedido precisa chegar com identificação suficiente do cliente e estar em uma situação elegível conforme as regras e a integração configuradas. Consulte o extrato da cliente para conferir a origem e o lançamento.'},
  {q:'O pedido precisa ser criado no Bling?',a:'Quando o Bling está conectado como fonte oficial, o pedido mostrado no Fidelizei é conciliado com o pedido do Bling. O número comercial exibido deve corresponder ao número do Bling; não crie uma segunda venda manual no Fidelizei para a mesma compra.'},
  {q:'E se a cliente for cadastrada depois que o pedido foi aberto?',a:'Se a adesão e o pedido elegível ocorrerem no mesmo dia comercial e o pedido puder ser vinculado à cliente pelo CPF, a integração pode creditar os pontos mesmo que o pedido tenha sido aberto antes do cadastro. Compras anteriores ao dia de adesão não devem ser consideradas automaticamente.'},
  {q:'O pedido apareceu sem cliente. Como corrigir?',a:'Compare o CPF do contato e do pedido no ERP com o CPF cadastrado no Fidelizei. Corrija o cadastro na fonte oficial e execute a sincronização/conciliação novamente; não crie pedido duplicado nem use apenas o nome para associar pessoas.'},
  {q:'O que acontece com pontos quando um pedido é cancelado ou excluído?',a:'Na integração com o Bling, o cancelamento ou a exclusão na origem é conciliado e pode gerar o estorno correspondente no extrato. Alterações de valor também devem refletir apenas a diferença. Confira a situação no ERP e no histórico do pedido.'},
  {q:'Posso corrigir saldo manualmente?',a:'Um responsável autorizado pode registrar crédito ou débito com justificativa na área de clientes. O ajuste deve ser usado para corrigir inconsistências reais, não para substituir a conciliação de pedidos; confira extrato e auditoria depois.'}
 ]},
 {title:'Recompensas, níveis e ofertas',items:[
  {q:'Qual a diferença entre recompensa e oferta?',a:'Recompensa é resgatada por pontos e gera um cupom/benefício para uso conforme as regras da loja. Oferta é um produto anunciado por preço especial no app: a cliente demonstra interesse/reserva e paga diretamente à loja; não consome pontos.'},
  {q:'Como funciona o cupom de recompensa?',a:'Após resgatar, a cliente recebe um código individual. O cupom fica indisponível para novo uso e a loja valida o código no atendimento; quando integrado ao PDV, o código pode ser associado ao pedido. Não reutilize cupons já consumidos ou expirados.'},
  {q:'Posso configurar validade e público para um benefício?',a:'A loja pode definir regras como validade e elegibilidade por nível quando essas opções estiverem disponíveis no catálogo. Confira as condições exibidas antes de publicar e teste o resgate com uma conta de cada nível.'},
  {q:'Quem recebe uma oferta de produto e como é feito o pagamento?',a:'A oferta aparece no ambiente da empresa para clientes elegíveis. A reserva sinaliza interesse e não representa pagamento confirmado. A loja combina pagamento, retirada/entrega, estoque e eventuais trocas diretamente com a cliente.'}
 ]},
 {title:'Acesso do cliente e privacidade',items:[
  {q:'A cliente precisa instalar um aplicativo?',a:'Não necessariamente: o Fidelizei funciona como aplicativo web responsivo. A cliente acessa pelo link ou QR Code da loja e pode instalar o atalho quando o navegador oferecer essa opção.'},
  {q:'O que aparece no cartão fidelidade virtual?',a:'O cartão pode mostrar identificação da cliente, CPF como número de fidelidade, nome e identidade visual da loja, data de adesão e código de barras para leitura no caixa. Trate CPF como dado pessoal: limite a visualização e a leitura ao atendimento necessário.'},
  {q:'Como a cliente redefine a senha?',a:'Na tela de acesso, ela pode iniciar a recuperação pelo canal disponível para a conta, e-mail ou WhatsApp quando configurado. Use somente o link/código temporário recebido; suporte ou loja não devem pedir a senha atual.'},
  {q:'Como são protegidos os dados dos clientes?',a:'A plataforma restringe acesso por empresa e perfil e mantém controles de credencial e auditoria. A loja continua responsável por base legal, consentimento, transparência e uso dos dados para a finalidade informada; consulte a Política de Privacidade e os Termos.'},
  {q:'Como funcionam campanhas por e-mail e WhatsApp?',a:'O envio depende de consentimento e da configuração válida dos provedores. E-mail exige domínio e serviço de envio configurados; WhatsApp pode exigir número e modelo de mensagem aprovado pela Meta. Verifique fila e logs antes de repetir um disparo.'}
 ]},
 {title:'Integrações e API',items:[
  {q:'Quais ERPs posso conectar hoje?',a:'O Bling é o conector homologado disponível no produto. Outros sistemas aparecem como desenvolvimento, planejamento ou dependência de parceria; status do marketplace não significa conexão ativa. Confirme a situação atual antes de contratar ou iniciar uma migração.'},
  {q:'Posso conectar outro sistema usando a API?',a:'Sim, para os recursos publicados pela API Fidelizei. A chave é criada no portal da empresa com escopos de consulta selecionados, e o sistema integrador consulta os endpoints documentados por HTTPS. Uma API_KEY sozinha não configura um conector de qualquer ERP: o sistema precisa conhecer a URL, o contrato dos endpoints, formato, paginação e regras de autenticação.'},
  {q:'Que dados a chave de consulta permite ler?',a:'Os escopos atuais selecionam conjuntos: clientes/fidelidade ou vendas. O escopo de clientes inclui campos pessoais como nome, e-mail, telefone, CPF e saldo; por isso, conceda-o somente quando necessário. A granularidade é por conjunto de dados, não por campo individual.'},
  {q:'Onde guardo a API_KEY?',a:'Copie a chave gerada uma única vez e guarde-a em um cofre de segredos ou variável de ambiente do servidor integrador. Não a coloque em código de navegador, repositório, aplicativo cliente, URL, planilha compartilhada ou log. Revogue a chave se houver exposição.'},
  {q:'A API tem homologação e limites?',a:'A URL documentada é a base de produção; não use produção para testes com dados reais sem autorização. As consultas aceitam paginação e estão sujeitas a limite por chave. Até existir ambiente sandbox isolado publicado, use dados de teste autorizados e faça homologação controlada.'}
 ]}
];

function Header(){const[open,setOpen]=useState(false);useEffect(()=>{const resize=()=>{if(window.innerWidth>1050)setOpen(false)};window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize)},[]);const close=()=>setOpen(false);return <header className={`site-header${open?' menu-open':''}`}><a href="/" className="site-logo" onClick={close}><BrandLogo/></a><button type="button" className="site-menu-toggle" aria-label={open?'Fechar menu':'Abrir menu'} aria-expanded={open} aria-controls="site-navigation" onClick={()=>setOpen(value=>!value)}>{open?<X/>:<Menu/>}</button><nav id="site-navigation"><a href="/produto" onClick={close}>Produto</a><a href="/solucoes/varejo" onClick={close}>Soluções</a><a href="/integracoes" onClick={close}>Integrações</a><a href="/planos" onClick={close}>Planos</a><a href="/blog" onClick={close}>Conteúdos</a><a className="site-mobile-link" href="/cliente" onClick={close}>Sou cliente</a><a className="site-mobile-link primary" href="/login" onClick={close}>Entrar como lojista</a></nav><div><a className="site-link" href="/cliente">Sou cliente</a><a className="site-button small" href="/login">Entrar como lojista</a></div>{open&&<button type="button" className="site-menu-backdrop" aria-label="Fechar menu" onClick={close}/>}</header>}
function Frame({children}:{children:React.ReactNode}){return <div className="public-site"><Header/>{children}<footer className="site-footer"><div><BrandLogo/><p>Relacionamento que vira recorrência, com dados, segurança e integração.</p></div><div><b>Produto</b><a href="/produto">Visão geral</a><a href="/integracoes">Integrações</a><a href="/planos">Planos</a><a href="/login">Portal do lojista</a></div><div><b>Recursos</b><a href="/blog">Central de conteúdo</a><a href="/faq">Perguntas frequentes</a><a href="/desenvolvedores">Desenvolvedores</a><a href="/seguranca">Segurança</a><a href="/contato">Contato</a></div><div><b>Cliente</b><a href="/cliente">Acessar programas</a><a href="/privacidade">Privacidade</a><a href="/termos">Termos de uso</a><a href="/cookies">Cookies</a></div><LegalFooter compact/></footer></div>}
export function PublicHome(){return <Frame><main><section className="site-hero"><div><span className="site-eyebrow"><Sparkles/> FIDELIDADE CONECTADA À OPERAÇÃO</span><h1>Faça seus clientes voltarem com um programa de fidelidade conectado ao seu ERP.</h1><p>O Fidelizei conecta vendas, pontos, recompensas e campanhas para sua loja criar relacionamento contínuo — com regras claras e a marca da sua empresa.</p><div className="site-actions"><a className="site-button" href="/planos">Começar 7 dias grátis <ArrowRight/></a><a className="site-button ghost" href="/produto">Conhecer a plataforma</a></div><small>Nenhuma cobrança durante o teste · Implantação guiada</small></div><div className="product-preview home-product-demo" aria-label="Demonstração ilustrativa da experiência de fidelidade no aplicativo"><div className="preview-head"><span><i className="preview-status-dot"/>Experiência no app do cliente</span><em>EXEMPLO ILUSTRATIVO</em></div><div className="member-demo-card"><div className="member-demo-brand"><span className="member-demo-mark">F</span><span><b>Clube da sua loja</b><small>Programa de fidelidade</small></span><Sparkles/></div><div className="member-demo-balance"><div><small>Saldo disponível</small><strong>1.250 <span>pontos</span></strong></div><span className="member-demo-pill"><Gift/> Benefícios</span></div><div className="member-demo-progress"><div><span>Próxima recompensa</span><b>75% do caminho</b></div><span className="progress-rail"><i/></span></div><div className="member-demo-reward"><span><Gift/></span><div><b>Benefício da loja</b><small>Regras e elegibilidade definidas pelo lojista</small></div><ChevronRight/></div></div><div className="demo-flow-caption"><span><i/> Pedido chega pelo ERP</span><ArrowRight/><span><i/> Pontos no extrato</span></div><small className="demo-disclaimer">Tela conceitual. Informações e saldos não são dados reais.</small></div></section><section className="site-trust"><span>Uma plataforma para toda a jornada</span><div><b>Bling conectado</b><b>Dados isolados por empresa</b><b>Experiência com a marca da loja</b><b>LGPD e rastreabilidade</b></div></section><section id="como-funciona" className="site-section"><span className="site-eyebrow">DO PEDIDO AO PRÓXIMO PEDIDO</span><h2>Fidelidade integrada à operação real.</h2><p className="section-lead">O Fidelizei organiza clientes, acompanha vendas, calcula pontos e entrega benefícios sem criar uma planilha paralela.</p><div className="journey"><article><Plug/><b>1. Conecte</b><p>Autorize o Bling pelo fluxo seguro OAuth ou use os recursos operacionais disponíveis no portal.</p></article><article><Database/><b>2. Organize</b><p>Clientes, pedidos, pontos e consentimentos ficam vinculados à empresa correta.</p></article><article><Megaphone/><b>3. Relacione</b><p>Crie recompensas por nível, ofertas e campanhas compatíveis com o plano.</p></article><article><BarChart3/><b>4. Acompanhe</b><p>Use dashboards e relatórios liberados para a maturidade da sua operação.</p></article></div></section><section className="site-section product-modules"><span className="site-eyebrow">PLATAFORMA</span><h2>Os módulos que sustentam o ciclo de fidelidade.</h2><div className="module-grid"><a href="/produto"><Users/><b>CRM e clientes</b><p>Cadastro, histórico, níveis e atendimento.</p></a><a href="/produto"><Gift/><b>Pontos e recompensas</b><p>Regras, validade, cupons de uso único e benefícios por nível.</p></a><a href="/produto"><Megaphone/><b>Relacionamento</b><p>Campanhas, ofertas e comunicação com consentimento.</p></a><a href="/integracoes"><Plug/><b>Integrações</b><p>Bling disponível e arquitetura preparada para novos conectores homologados.</p></a><a href="/produto"><BarChart3/><b>Gestão</b><p>Indicadores operacionais e gerenciais conforme o plano.</p></a><a href="/seguranca"><ShieldCheck/><b>Governança</b><p>Perfis, MFA, auditoria e isolamento entre empresas.</p></a></div></section><section className="site-section integration-showcase"><div><span className="site-eyebrow">INTEGRAÇÕES SEM PROMESSAS VAZIAS</span><h2>Conectores com status e documentação claros.</h2><p>A integração Bling usa autorização OAuth, tokens JWT renováveis, webhooks autenticados e conciliação. Novos conectores só serão anunciados como disponíveis depois de homologados.</p><a className="site-button ghost" href="/integracoes">Ver marketplace de integrações</a></div><article><Plug/><div><small>DISPONÍVEL</small><b>Bling</b><span>Pedidos, clientes, pontuação e estorno conforme os dados e permissões da conta.</span></div></article></section><section className="site-section dark"><div><span className="site-eyebrow">CONTROLE E SEGURANÇA</span><h2>Pronto para operar. Preparado para evoluir.</h2><p>Perfis de acesso, trilha de auditoria, autenticação multifator, isolamento por empresa e monitoramento dão sustentação à operação.</p></div><div className="security-list"><span><ShieldCheck/> Acessos por perfil e empresa</span><span><LockKeyhole/> Senhas protegidas e MFA</span><span><Database/> Histórico e rastreabilidade</span><a href="/seguranca">Conheça a arquitetura de segurança <ArrowRight/></a></div></section><section className="site-section faq-section"><span className="site-eyebrow">PERGUNTAS FREQUENTES</span><h2>Antes de começar.</h2><details><summary>Como os pontos são calculados?</summary><p>A empresa configura suas regras. Em vendas identificadas e elegíveis, o Fidelizei calcula os pontos e registra a movimentação no extrato do cliente.</p></details><details><summary>O que acontece quando um pedido é cancelado?</summary><p>Na integração Bling, pedidos cancelados ou excluídos são conciliados e os pontos correspondentes podem ser estornados automaticamente.</p></details><details><summary>O cliente precisa instalar um aplicativo?</summary><p>O acesso funciona como aplicativo web responsivo e pode ser instalado no celular quando o navegador oferecer essa opção.</p></details><details><summary>Outros ERPs já estão disponíveis?</summary><p>O conector Bling está disponível. Outros provedores só serão publicados como disponíveis após implementação e homologação.</p></details><a className="faq-more-link" href="/faq">Ver todas as dúvidas e respostas <ArrowRight/></a></section><section className="site-cta"><div><h2>Comece com o plano certo para o seu momento.</h2><p>Todos os planos possuem 7 dias grátis; recursos e limites são aplicados de verdade pela assinatura.</p></div><a className="site-button" href="/planos">Comparar planos <ArrowRight/></a></section></main></Frame>}

type TrialForm={companyName:string;legalName:string;cnpj:string;responsibleName:string;email:string;phone:string;password:string;postalCode:string;address:string;addressNumber:string;complement:string;district:string;city:string;state:string;paymentMethod:'boleto'|'card'};
const emptyTrial:TrialForm={companyName:'',legalName:'',cnpj:'',responsibleName:'',email:'',phone:'',password:'',postalCode:'',address:'',addressNumber:'',complement:'',district:'',city:'',state:'',paymentMethod:'boleto'};

export function PublicPlans(){
 const[data,setData]=useState<{plans:Plan[];trialDays:number;billing?:{configured:boolean;enabled:boolean}}> (),[selected,setSelected]=useState<Plan>(),[message,setMessage]=useState(''),[form,setForm]=useState<TrialForm>(emptyTrial),[lookup,setLookup]=useState<'cnpj'|'cep'>(),[submitting,setSubmitting]=useState(false),[contractAccepted,setContractAccepted]=useState(false),[termsAccepted,setTermsAccepted]=useState(false),[minimumTermAccepted,setMinimumTermAccepted]=useState(false),[billingAccepted,setBillingAccepted]=useState(false);
 useEffect(()=>{api('/public/plans').then(setData);const params=new URLSearchParams(location.search),status=params.get('checkout'),token=params.get('token');if(status&&token&&['success','cancel','expired'].includes(status)){api('/public/trials/billing-confirm',{method:'POST',body:JSON.stringify({token,status})}).then(()=>setMessage(status==='success'?'Cartão cadastrado com segurança. Seu teste está ativo e nada será cobrado antes do 7º dia.':'O cadastro do cartão não foi concluído. Entre no portal para regularizar a forma de pagamento.')).catch(error=>setMessage((error as Error).message));history.replaceState({},'',location.pathname)}},[]);
 const change=(key:keyof TrialForm,value:string)=>setForm(current=>({...current,[key]:value}));
 async function lookupCnpj(){const value=form.cnpj.replace(/\D/g,'');if(value.length!==14)return;setLookup('cnpj');setMessage('Consultando o CNPJ na BrasilAPI…');try{const item=await api<Partial<TrialForm>>(`/public/cnpj/${value}`);setForm(current=>({...current,...Object.fromEntries(Object.entries(item).filter(([,v])=>v))}));setMessage('Dados da empresa preenchidos. Revise antes de continuar.')}catch(error){setMessage((error as Error).message)}finally{setLookup(undefined)}}
 async function lookupCep(){const value=form.postalCode.replace(/\D/g,'');if(value.length!==8)return;setLookup('cep');setMessage('Consultando o endereço…');try{const item=await api<Partial<TrialForm>>(`/public/cep/${value}`);setForm(current=>({...current,...Object.fromEntries(Object.entries(item).filter(([,v])=>v))}));setMessage('Endereço preenchido. Informe o número e revise os dados.')}catch(error){setMessage((error as Error).message)}finally{setLookup(undefined)}}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!selected)return;if(!contractAccepted||!termsAccepted||!minimumTermAccepted||!billingAccepted){setMessage('Confirme o contrato, os termos, a fidelidade mínima e a cobrança para continuar.');return}setSubmitting(true);setMessage('Registrando o aceite e preparando sua assinatura…');try{const result=await api<{trialEndsAt:string;checkoutUrl?:string;billingWarning?:string}>('/public/trials',{method:'POST',body:JSON.stringify({...form,planCode:selected.code,acceptContract:contractAccepted,acceptTerms:termsAccepted,minimumTermConsent:minimumTermAccepted,billingConsent:billingAccepted})});if(result.checkoutUrl){setMessage('Aceite registrado. Abrindo o Asaas para cadastrar o cartão com segurança…');location.assign(result.checkoutUrl);return}setMessage(`${result.billingWarning||'Ambiente, contrato e cobrança futura configurados.'} Seu teste vai até ${new Date(result.trialEndsAt).toLocaleDateString('pt-BR')}. Redirecionando…`);setTimeout(()=>location.href='/login',2200)}catch(error){setMessage((error as Error).message);setSubmitting(false)}}
 const trialEnd=new Date(Date.now()+7*86_400_000).toLocaleDateString('pt-BR');
 return <Frame><main><section className="plans-hero"><span className="site-eyebrow">PLANOS TRANSPARENTES</span><h1>Evolua os recursos conforme sua operação cresce.</h1><p>O essencial nunca é bloqueado: CRM, fidelidade, aplicativo do cliente, relatórios básicos e acesso às integrações ERP disponíveis faz parte da plataforma.</p><b>7 dias grátis em qualquer plano · sem cobrança durante o teste</b></section><section className="plan-grid">{data?.plans.map(plan=><article className={plan.highlight?'featured':''} key={plan.code}>{plan.highlight&&<em>Mais escolhido</em>}<h2>{plan.name}</h2><p>{plan.tagline}</p><strong>{money(plan.monthlyPriceCents)}<small>/mês</small></strong><ul><li><Users/>Até {plan.userLimit} usuários</li><li><Database/>{plan.consumerLimit.toLocaleString('pt-BR')} consumidores</li><li><Database/>{plan.storageMb>=1024?`${plan.storageGb} GB`:`${plan.storageMb} MB`} de armazenamento</li>{plan.features.map(feature=><li key={feature}><Check/>{labels[feature]||feature}</li>)}</ul><button className="site-button" onClick={()=>{setSelected(plan);setForm(emptyTrial);setContractAccepted(false);setTermsAccepted(false);setMinimumTermAccepted(false);setBillingAccepted(false);setMessage('')}}>Testar {plan.name} grátis</button></article>)}</section><section className="comparison"><h2>Comparativo objetivo</h2><p>Recursos liberados tecnicamente pelo plano, não apenas uma descrição comercial.</p><div className="comparison-table"><div className="comparison-head"><b>Capacidade</b>{data?.plans.map(p=><b key={p.code}>{p.name}</b>)}</div>{Object.entries(labels).map(([key,label])=><div key={key}><span>{label}</span>{data?.plans.map(p=><i className={p.features.includes(key)?'yes':''} key={p.code}>{p.features.includes(key)?<Check/>:'—'}</i>)}</div>)}</div></section>{selected&&<div className="trial-modal" role="dialog" aria-modal="true" aria-label={`Teste do plano ${selected.name}`}><form onSubmit={submit}><button type="button" className="trial-close" aria-label="Fechar" onClick={()=>setSelected(undefined)}><X/></button><span className="site-eyebrow">7 DIAS GRÁTIS · {selected.name.toUpperCase()}</span><h2>Crie seu ambiente Fidelizei</h2><div className="trial-free-notice"><ShieldCheck/><div><b>Nada será cobrado antes de {trialEnd}.</b><span>Sem cancelamento, depois dos 7 dias será cobrado o valor integral de {money(selected.monthlyPriceCents)} por mês.</span></div></div>
 <fieldset><legend><Building2/> Empresa e acesso</legend><div className="trial-form-grid"><label>CNPJ<div className="input-action"><input value={form.cnpj} onChange={e=>change('cnpj',e.target.value)} onBlur={lookupCnpj} inputMode="numeric" placeholder="00.000.000/0000-00" required/><button type="button" onClick={lookupCnpj} aria-label="Consultar CNPJ">{lookup==='cnpj'?<LoaderCircle className="spin"/>:<Search/>}</button></div></label><label>Nome fantasia<input value={form.companyName} onChange={e=>change('companyName',e.target.value)} required/></label><label className="wide">Razão social<input value={form.legalName} onChange={e=>change('legalName',e.target.value)} required/></label><label>Responsável<input value={form.responsibleName} onChange={e=>change('responsibleName',e.target.value)} required/></label><label>E-mail de acesso<input value={form.email} onChange={e=>change('email',e.target.value)} type="email" required/></label><label>Celular<input value={form.phone} onChange={e=>change('phone',e.target.value)} inputMode="tel" required/></label><label>Senha inicial<input value={form.password} onChange={e=>change('password',e.target.value)} type="password" minLength={10} required/></label></div></fieldset>
 <fieldset><legend><MapPin/> Endereço de cobrança</legend><div className="trial-form-grid"><label>CEP<div className="input-action"><input value={form.postalCode} onChange={e=>change('postalCode',e.target.value)} onBlur={lookupCep} inputMode="numeric" required/><button type="button" onClick={lookupCep} aria-label="Consultar CEP">{lookup==='cep'?<LoaderCircle className="spin"/>:<Search/>}</button></div></label><label>Logradouro<input value={form.address} onChange={e=>change('address',e.target.value)} required/></label><label>Número<input value={form.addressNumber} onChange={e=>change('addressNumber',e.target.value)} required/></label><label>Complemento<input value={form.complement} onChange={e=>change('complement',e.target.value)}/></label><label>Bairro<input value={form.district} onChange={e=>change('district',e.target.value)} required/></label><label>Cidade<input value={form.city} onChange={e=>change('city',e.target.value)} required/></label><label>UF<input value={form.state} onChange={e=>change('state',e.target.value.toUpperCase().slice(0,2))} maxLength={2} required/></label></div></fieldset>
 <fieldset><legend><CreditCard/> Como deseja pagar após o teste?</legend><div className="payment-options"><label className={form.paymentMethod==='boleto'?'active':''}><input type="radio" checked={form.paymentMethod==='boleto'} onChange={()=>change('paymentMethod','boleto')}/><ReceiptText/><span><b>Boleto bancário</b><small>Gerado e enviado somente ao fim dos 7 dias.</small></span></label><label className={form.paymentMethod==='card'?'active':''}><input type="radio" checked={form.paymentMethod==='card'} onChange={()=>change('paymentMethod','card')} disabled={!data?.billing?.configured||!data?.billing?.enabled}/><CreditCard/><span><b>Cartão de crédito</b><small>Cadastro seguro no Asaas; débito automático somente no 7º dia.</small></span></label></div><div className="payment-security"><ShieldCheck/><span><b>Pagamento processado com segurança pelo Asaas</b><small>O Fidelizei não armazena os dados do seu cartão.</small></span></div>{(!data?.billing?.configured||!data?.billing?.enabled)&&<small className="gateway-warning">Cartão temporariamente indisponível. O boleto continua disponível.</small>}</fieldset>
 <div className="trial-acceptances"><label className="trial-terms contract-consent"><input type="checkbox" required checked={contractAccepted} onChange={e=>setContractAccepted(e.target.checked)}/><span>Li, compreendi e aceito integralmente o <a href="/contrato-licenca" target="_blank" rel="noreferrer">Contrato de Licença de Uso de Software e Prestação de Serviços Tecnológicos</a>.</span></label><label className="trial-terms"><input type="checkbox" required checked={termsAccepted} onChange={e=>setTermsAccepted(e.target.checked)}/><span>Li e aceito os <a href="/termos" target="_blank" rel="noreferrer">Termos de Uso</a> e a <a href="/privacidade" target="_blank" rel="noreferrer">Política de Privacidade</a>.</span></label><label className="trial-terms minimum-term-consent"><input type="checkbox" required checked={minimumTermAccepted} onChange={e=>setMinimumTermAccepted(e.target.checked)}/><span>Estou ciente da <b>permanência mínima de 6 meses</b> e de que o cancelamento antecipado poderá gerar multa de 50% das mensalidades restantes, conforme o contrato.</span></label><label className="trial-terms billing-consent"><input type="checkbox" required checked={billingAccepted} onChange={e=>setBillingAccepted(e.target.checked)}/><span>Estou ciente de que nada será cobrado nos primeiros 7 dias. Sem cancelamento até {trialEnd}, será cobrado o valor integral de <b>{money(selected.monthlyPriceCents)}/mês</b> por {form.paymentMethod==='boleto'?'boleto':'cartão'}.</span></label></div>{message&&<div className="trial-message" role="status">{message}</div>}<button className="site-button" disabled={submitting}>{submitting?<><LoaderCircle className="spin"/>Processando…</>:form.paymentMethod==='card'?'Aceitar e continuar no Asaas':'Aceitar contrato e ativar teste'}</button></form></div>}</main></Frame>}

type GuideSection={title:string;items:string[]};
type Guide={slug:string;tag:string;title:string;summary:string;audience:string;duration:string;path:string;prerequisites:string[];sections:GuideSection[];validation:string[];troubleshooting:string[];links?:{label:string;url:string}[]};
const guides:Guide[]=[
 {slug:'primeiros-passos',tag:'Comece aqui',title:'Coloque sua loja para operar com segurança',summary:'Um roteiro completo da identidade visual até a primeira compra pontuada.',audience:'Proprietário e gerente',duration:'20–30 min',path:'Portal do lojista → Configurações',prerequisites:['CNPJ, e-mail e celular da loja revisados','Logo em PNG ou JPEG','Regra comercial do programa aprovada pela loja'],sections:[{title:'1. Complete o ambiente',items:['Abra Configurações e revise razão social, CNPJ, responsável, telefone e e-mail.','Envie a logo da loja: no aplicativo do cliente será exibida somente a identidade da loja.','Cadastre usuários internos com acessos individuais; não compartilhe a conta do proprietário.']},{title:'2. Configure a fidelidade',items:['Defina a regra de pontos por real, validade e critérios de resgate.','Cadastre recompensas por pontos e ofertas pagas em áreas separadas.','Revise os textos e condições antes de publicar no aplicativo.']},{title:'3. Homologue antes de divulgar',items:['Cadastre uma cliente teste com CPF, e-mail e celular válidos.','Registre ou sincronize um pedido identificado e confira o extrato de pontos.','Cancele o pedido, confirme o estorno e reative somente se o ERP também reativar.']}],validation:['Cliente consegue entrar novamente com a senha cadastrada','Pedido aparece com cliente identificado','Saldo, extrato e cancelamento permanecem coerentes','Logo e nome da loja aparecem corretamente no aplicativo'],troubleshooting:['Pedido sem cliente: compare o CPF/telefone do pedido com o cadastro da cliente.','Pontos não gerados: confira situação do pedido, regra vigente e data da venda.','Acesso falha: use a redefinição por e-mail/WhatsApp e confirme que o cadastro está ativo.']},
 {slug:'bling',tag:'Integrações',title:'Conectar e homologar o Bling',summary:'Conexão OAuth guiada, sincronização de clientes e pedidos e teste de estorno automático.',audience:'Proprietário da loja',duration:'15–25 min',path:'Portal do lojista → Configurações → Integração Bling',prerequisites:['Conta Bling com permissão para autorizar aplicativos','CPF ou celular preenchido nos contatos/pedidos','Situações de pedido de venda organizadas no Bling'],sections:[{title:'1. Autorize sem copiar tokens',items:['Clique em Conectar Bling. O Fidelizei abrirá a autorização oficial do Bling.','Entre na conta correta, confira as permissões e autorize.','Ao retornar, confirme que o cartão mostra Conectado e a data da conexão.']},{title:'2. Faça a primeira sincronização',items:['Clique em Sincronizar agora; o processamento ocorre em fila e não bloqueia a operação.','Confira o resumo de clientes e novas vendas importadas.','Abra Vendas e filtre pela origem Bling para validar pedido, cliente, valor e situação.']},{title:'3. Homologue o ciclo completo',items:['Crie um pedido teste para uma cliente já cadastrada no aplicativo.','Confirme que o pedido pontuou uma única vez.','Cancele/exclua no Bling e confirme o estorno automático; depois teste a reativação.','Não use o botão repetidamente para corrigir duplicidade: a integração é idempotente.']}],validation:['Status Conectado e data da última sincronização visíveis','Pedido aparece uma única vez com origem Bling','Cliente é identificado pelo documento/contato','Cancelamento gera estorno e reativação aplica somente a diferença'],troubleshooting:['HTTP 403 no mapa de situações: o Fidelizei usa os códigos do pedido e continua a sincronização.','Cliente não identificado: preencha o CPF no contato/pedido e execute nova sincronização.','Autorização expirada: desconecte e faça o OAuth novamente, sem reutilizar token antigo.'],links:[{label:'Documentação oficial da API Bling',url:'https://developer.bling.com.br/bling-api'},{label:'Webhooks oficiais do Bling',url:'https://developer.bling.com.br/webhooks'}]},
 {slug:'integracao-erp',tag:'Integrações',title:'Preparar uma integração com outro ERP',summary:'Entenda o contrato de dados e o processo necessário para desenvolver e homologar um novo conector.',audience:'Proprietário e equipe técnica',duration:'30–60 min',path:'Documentação técnica → Arquitetura de integrações',prerequisites:['Documentação técnica oficial do ERP','Responsável técnico pelo sistema de origem','Ambiente e dados de homologação antes de qualquer liberação comercial'],sections:[{title:'1. Avalie a viabilidade',items:['Confirme se o ERP oferece OAuth ou credencial segura, API documentada, limites e ambiente de teste.','Liste os eventos necessários: cliente, venda, atualização, cancelamento e exclusão.','Não anuncie o conector como disponível antes da homologação ponta a ponta.']},{title:'2. Defina o contrato mínimo',items:['Cliente: identificador externo estável, nome, CPF, e-mail e celular quando autorizados.','Venda: identificador externo, pedido, cliente, valor, data, origem e situação.','Cancelamento: mesmo identificador da venda, situação e data do evento.','Nunca use apenas o nome para conciliar pessoas ou transações.']},{title:'3. Implemente com resiliência',items:['Prefira webhook autenticado para eventos e API para carga inicial e conciliação.','Implemente idempotência, ordenação, retentativas limitadas e observabilidade por empresa.','Proteja credenciais no servidor e documente o fluxo antes de liberar o conector.']}],validation:['Autorização, renovação e revogação foram testadas quando aplicáveis','Carga inicial não cria clientes ou vendas duplicados','Nova venda chega uma vez e gera pontos conforme a regra','Cancelamento do ERP estorna a movimentação correta'],troubleshooting:['Erro de conexão: valide credenciais, escopos, HTTPS, limites e disponibilidade do provedor.','Dados duplicados: mantenha o mesmo identificador externo em todas as atualizações.','ERP sem webhook: use conciliação periódica por API; CSV fica restrito a processo assistido e auditável.']},
 {slug:'api-publica',tag:'API',title:'Usar a API pública com escopo mínimo',summary:'Crie uma chave, consulte clientes e vendas e mantenha governança de credenciais.',audience:'Equipe técnica',duration:'15–30 min',path:'Portal do lojista → Configurações → Chaves da API',prerequisites:['Plano com o recurso API pública','Integração capaz de usar HTTPS e Bearer Token','Responsável definido pela rotação da credencial'],sections:[{title:'1. Gere a chave',items:['Clique em Nova chave e use o nome do sistema consumidor.','Copie o valor fz_live_ imediatamente: ele não será exibido outra vez.','Armazene em cofre de segredos ou variável de ambiente, nunca no código-fonte.']},{title:'2. Faça a primeira consulta',items:['Use Authorization: Bearer SUA_CHAVE.','Consulte GET https://api.fidelizaplus.com.br/public/v1/customers para clientes.','Consulte GET https://api.fidelizaplus.com.br/public/v1/sales para vendas.','A resposta é isolada à empresa dona da chave e limitada a 500 registros por consulta.']},{title:'3. Opere com governança',items:['Crie uma chave diferente por integração.','Revogue a chave assim que o sistema deixar de ser utilizado.','Trate HTTP 401, 403 e 429 sem repetir requisições indefinidamente.']}],validation:['Consulta retorna HTTP 200 e o campo data','Último uso aparece atualizado no portal','Chave sem escopo recebe HTTP 403','Chave revogada deixa de autenticar'],troubleshooting:['HTTP 401: confira prefixo fz_live_, Bearer e chave ativa.','HTTP 403: recurso ou escopo não está no plano/chave.','HTTP 429: reduza a frequência; o limite atual é 120 requisições por minuto por chave.']},
 {slug:'campanhas',tag:'Relacionamento',title:'Criar campanhas, teste A/B e medir receita',summary:'Da campanha vigente à atribuição de venda, com consentimento e métricas úteis.',audience:'Marketing e gerente',duration:'20–40 min',path:'Portal do lojista → Campanhas',prerequisites:['Clientes com consentimento de marketing válido','Campanha de pontos dentro da vigência','Canal de comunicação configurado'],sections:[{title:'1. Prepare a campanha',items:['Defina objetivo, período, benefício e público antes de escrever a mensagem.','Use segmentos claros: todos, ativos, inativos ou VIP.','Para WhatsApp, selecione um modelo previamente aprovado pela Meta.']},{title:'2. Configure o experimento',items:['Abra Experimentos e receita atribuída e selecione uma campanha vigente.','Escreva variantes A e B mudando apenas um elemento principal.','Defina a janela de atribuição em dias e ative o experimento.']},{title:'3. Leia o resultado',items:['Compare entregas, cliques/conversões e receita atribuída por variante.','Não encerre com amostra muito pequena.','Transforme a variante vencedora no novo padrão e registre o aprendizado.']}],validation:['Campanha vigente aparece no seletor','Clientes sem consentimento não entram na fila','Variantes recebem divisão de público','Venda dentro da janela aparece como receita atribuída'],troubleshooting:['Seletor vazio: campanha precisa estar ativa e entre início e fim.','WhatsApp não envia: confirme modelo aprovado, idioma e variáveis.','Atribuição zerada: revise janela, identificação da cliente e data da compra.']},
 {slug:'recompensas-ofertas',tag:'Fidelidade',title:'Publicar recompensas e ofertas sem confundir os fluxos',summary:'Use pontos para recompensas e pagamento direto à loja para ofertas exclusivas.',audience:'Operação e marketing',duration:'15–25 min',path:'Portal do lojista → Campanhas / Catálogo',prerequisites:['Saldo e regras de fidelidade validados','Imagem e condições comerciais do item','Estoque e período definidos'],sections:[{title:'Recompensa por pontos',items:['Cadastre cupom ou benefício com custo em pontos e estoque.','No resgate, o cliente recebe um código de uso único.','A loja valida o código no atendimento e o vincula ao pedido.']},{title:'Oferta exclusiva paga',items:['Cadastre produto, foto, preço original, preço exclusivo, estoque e validade.','O cliente reserva no aplicativo e recebe um código com prazo.','O pagamento ocorre diretamente para a loja; depois a equipe confirma a conversão e o pedido.']},{title:'Gestão diária',items:['Pause itens indisponíveis em vez de deixar condições vencidas públicas.','Acompanhe reservas abertas, expiradas e convertidas.','Use fotos próprias e descreva retirada, frete, troca e pagamento.']}],validation:['Item publicado aparece no aplicativo correto','Estoque diminui na reserva quando configurado','Código não pode ser reutilizado','Conversão registra pedido e pagamento sem consumir pontos na oferta paga'],troubleshooting:['Item não aparece: confira status, datas, estoque e plano.','Código expirado: faça nova reserva se ainda houver disponibilidade.','Imagem falha: reduza o arquivo e confira a franquia de armazenamento.']},
 {slug:'comunicacao',tag:'Comunicação',title:'E-mail e WhatsApp: configuração e diagnóstico',summary:'Entenda o que a loja controla e o que depende dos provedores Resend e Meta.',audience:'Proprietário e administrador técnico',duration:'20–45 min',path:'Portal do lojista → Campanhas / Recuperação de senha',prerequisites:['E-mail e celular válidos nos cadastros','Consentimento para WhatsApp quando exigido','Domínio e modelos aprovados nos provedores'],sections:[{title:'E-mail',items:['O remetente oficial usa domínio verificado; o cliente deve ter e-mail obrigatório e válido.','Mensagens de boas-vindas e redefinição entram na fila automática.','Se não chegar, confira spam, domínio, chave de envio e logs do provedor.']},{title:'WhatsApp',items:['Use o número no padrão brasileiro com DDD.','Fora da janela de atendimento, a Meta exige um modelo aprovado.','Para recuperação de senha, o código é temporário e de uso único.']},{title:'Boas práticas',items:['Nunca envie senha em texto puro.','Não reutilize tokens entre produção e homologação.','Monitore falhas e mantenha alternativa por e-mail.']}],validation:['Mensagem aparece como enviada no provedor','Cliente recebe no endereço/número cadastrado','Código funciona uma vez e expira','Consentimento e canal ficam registrados'],troubleshooting:['WhatsApp não chega: confirme modelo fideliza_password_reset aprovado e variáveis na ordem correta.','E-mail rejeitado: valide o domínio e a variável RESEND_API_KEY.','Celular inválido: salve apenas DDD + número, sem ramal.'],links:[{label:'Chaves oficiais do Resend',url:'https://resend.com/docs/dashboard/api-keys/introduction'},{label:'Documentação WhatsApp Cloud API',url:'https://developers.facebook.com/docs/whatsapp/cloud-api/'}]},
 {slug:'cobranca-assinatura',tag:'Assinatura',title:'Entender plano, cobrança e atualização de pagamento',summary:'Saiba como o teste, o preço contratado, o vencimento e a conciliação funcionam.',audience:'Proprietário e financeiro',duration:'10–15 min',path:'Portal do lojista → Configurações → Plano atual',prerequisites:['Cadastro empresarial completo','Plano selecionado','E-mail financeiro válido'],sections:[{title:'Durante o teste',items:['Todos os planos começam com 7 dias grátis e sem cobrança imediata.','O plano atual mostra limites de usuários, consumidores, armazenamento e recursos.','Solicite mudança de plano pelo próprio portal quando precisar evoluir.']},{title:'Após contratação',items:['O preço vigente no momento da adesão é registrado na assinatura.','A cobrança é preparada antes do vencimento e conciliada pelo gateway.','Mudanças de preço no catálogo não alteram retroativamente uma assinatura existente.']},{title:'Acompanhamento',items:['Mantenha CNPJ, telefone e e-mail financeiro corretos.','Consulte vencimento e situação do plano no portal.','Em divergência, abra chamado informando empresa, competência e cobrança.']}],validation:['Plano e preço contratado aparecem no portal','Vencimento e status estão coerentes','Pagamento confirmado é conciliado sem baixa manual','Mudança solicitada possui acompanhamento'],troubleshooting:['Cobrança não gerada: complete telefone, CNPJ e responsável.','Pagamento não baixou: aguarde o webhook e solicite sincronização somente se necessário.','Valor divergente: compare assinatura, mudança aprovada e competência.'],links:[{label:'Webhooks oficiais do Asaas',url:'https://docs.asaas.com/docs/sobre-os-webhooks'}]},
 {slug:'seguranca',tag:'Segurança',title:'Proteger acessos, dados e integrações',summary:'Aplique MFA, perfis, consentimento, rotação de chaves e auditoria.',audience:'Proprietário e gestores',duration:'15–20 min',path:'Portal do lojista → Configurações',prerequisites:['Lista atual de usuários internos','Responsáveis por cada integração','Celular e e-mail de recuperação atualizados'],sections:[{title:'Acessos humanos',items:['Cada pessoa deve usar seu próprio usuário.','Conceda Operador, Gerente ou Proprietário conforme a responsabilidade.','Ative MFA para proprietários e gestores e desative acessos no desligamento.']},{title:'Integrações',items:['Use escopo mínimo, HTTPS e credenciais separadas por ambiente.','Nunca envie token por mensagem ou coloque em planilha.','Revogue e substitua uma chave exposta imediatamente.']},{title:'Privacidade',items:['Colete somente dados necessários para fidelidade e comunicação.','Respeite consentimento, finalidade e solicitações de titular.','Use logs e histórico para investigar ações sem alterar evidências.']}],validation:['Não existem contas compartilhadas','MFA ativo em contas privilegiadas','Chaves têm nome, dono e data de revisão','Clientes sem consentimento não recebem campanhas'],troubleshooting:['Acesso suspeito: desative o usuário, encerre sessões e altere a senha.','Chave exposta: revogue antes de gerar a substituta.','Possível incidente: preserve logs, registre horários e acione o suporte.']},
 {slug:'pedidos-e-pontos',tag:'Vendas e fidelidade',title:'Diagnosticar pedidos sem pontos ou com cliente não identificado',summary:'Confira identificação por CPF, regra de elegibilidade, data de adesão, duplicidades e conciliação de cancelamento.',audience:'Operação da loja',duration:'10–20 min',path:'Portal do lojista → Vendas / Clientes',prerequisites:['Acesso ao ERP ou PDV de origem','CPF da cliente no cadastro da loja','Número comercial do pedido'],sections:[{title:'1. Confirme a origem e o número',items:['Se o Bling estiver conectado, localize o pedido no Bling e compare o número, valor, data e situação.','O Fidelizei deve conciliar a venda oficial do ERP; não cadastre uma cópia do mesmo pedido.','Confira se o pedido está em uma situação elegível conforme configuração da loja.']},{title:'2. Confira o vínculo com a cliente',items:['Compare o CPF do contato no ERP e o CPF da conta Fidelizei, sem pontuar só pelo nome.','Se o cliente foi cadastrado no mesmo dia, confirme a data local do pedido e a data de adesão.','Se o pedido veio antes da adesão no mesmo dia, execute nova conciliação após corrigir o contato.']},{title:'3. Corrija na fonte',items:['Atualize cliente, valor ou situação no sistema oficial da venda.','Aguarde o webhook ou execute sincronização manual uma vez e consulte o extrato.','Em cancelamento ou exclusão, confirme o estorno correspondente e preserve o histórico.']}],validation:['Pedido aparece uma vez com identificador e número da origem','Cliente corresponde ao CPF esperado','Pontos e estornos batem com a regra da loja'],troubleshooting:['Cliente não vinculado: corrija CPF no ERP e sincronize novamente.','Pontos ausentes: valide adesão no mesmo dia, situação e regra vigente.','Duplicado ou valor incorreto: não crie outro pedido; solicite conciliação e confira a origem.']},
 {slug:'acesso-cartao-cliente',tag:'Aplicativo do cliente',title:'Acesso da cliente, cartão virtual e recuperação de senha',summary:'Como a cliente acessa o programa da loja, encontra seu cartão e recupera o acesso com segurança.',audience:'Atendimento e cliente final',duration:'8–12 min',path:'Link/QR Code da loja → Área da cliente',prerequisites:['Link ou QR Code correto da loja','E-mail e celular atualizados no cadastro','Programa da empresa publicado'],sections:[{title:'1. Acessar a loja certa',items:['Abra o link ou leia o QR Code da loja; confira nome e identidade visual antes de informar dados.','Entre com as credenciais cadastradas. Não compartilhe acesso entre familiares.','Se a loja não aparecer, peça o link/QR Code correto ao estabelecimento.']},{title:'2. Consultar o cartão fidelidade',items:['Na tela inicial, confira nome da loja, nome da cliente, data de adesão e saldo exibidos.','O código de barras do cartão representa o CPF para identificação no caixa; trate-o como dado pessoal e não publique uma captura de tela.','O código de um cupom é diferente do código de barras do cartão e só serve para validar aquele resgate.']},{title:'3. Recuperar acesso',items:['Use “Esqueci minha senha” e selecione o canal disponível para a conta.','Use o link ou código temporário recebido; ele expira e não deve ser reutilizado.','Se os canais estiverem desatualizados, a loja deve confirmar a identidade e corrigir cadastro pelo procedimento seguro.']}],validation:['A cliente entrou no ambiente da loja correta','Cartão e saldo correspondem ao cadastro','Link/código de recuperação funciona uma vez e expira'],troubleshooting:['Senha não aceita: confira e-mail da conta, Caps Lock e redefina uma vez.','Mensagem não chegou: confira spam, telefone, canal habilitado e dados cadastrados.','Cartão não aparece: peça à loja para confirmar que a adesão foi concluída.']},
 {slug:'ajuste-manual-pontos',tag:'Operação',title:'Corrigir saldo de pontos com crédito ou débito auditável',summary:'Procedimento para resolver uma divergência sem apagar o histórico nem duplicar pontos do ERP.',audience:'Gerente e proprietário',duration:'8–15 min',path:'Portal do lojista → Clientes → Selecionar cliente → Ajustar pontos',prerequisites:['Perfil autorizado para administrar clientes','Extrato e pedido de origem revisados','Justificativa e comprovante da divergência'],sections:[{title:'1. Investigue antes de ajustar',items:['Compare pedido oficial, cliente identificado, situação, regra de pontos e extrato.','Se a origem for Bling, corrija o pedido no Bling e aguarde a conciliação antes de lançar ajuste manual.','Confirme que não existe ajuste anterior para o mesmo problema.']},{title:'2. Registre a correção',items:['Selecione crédito ou débito e informe a quantidade exata de pontos.','Registre justificativa clara, referência do pedido e responsável conforme a política da loja.','Confirme o saldo posterior e avise a cliente pelo canal permitido.']},{title:'3. Revise a auditoria',items:['Verifique novo lançamento no extrato, saldo anterior e saldo atualizado.','Guarde evidências da análise sem colocar CPF ou dados sensíveis em mensagens públicas.','Se o ajuste estiver incorreto, registre ajuste compensatório em vez de tentar apagar evidências.']}],validation:['Saldo final confere com o cálculo documentado','Extrato preserva o lançamento de crédito/débito','Responsável e justificativa estão rastreáveis'],troubleshooting:['Botão indisponível: confira perfil de acesso e plano da loja.','Saldo divergente após sincronização: investigue se a origem voltou a recalcular o pedido.','Ajuste duplicado: pare novos lançamentos e abra chamado com IDs e horários.']},
 {slug:'chaves-api-permissoes',tag:'API',title:'Escolher permissões e conectar um sistema à API Fidelizei',summary:'Gere uma API_KEY de consulta, limite acesso a clientes ou vendas e configure o sistema consumidor sem expor o segredo.',audience:'Proprietário e desenvolvedor',duration:'10–20 min',path:'Portal do lojista → Integrações → Chaves da API',prerequisites:['Plano com API pública ativa','Conta de proprietário no Fidelizei','Servidor integrador que aceite segredo por variável de ambiente'],sections:[{title:'1. Escolha o que o sistema pode consultar',items:['Abra Nova chave e selecione Somente consulta.','Marque apenas Clientes e fidelidade (customers:read) e/ou Vendas (sales:read).','Clientes inclui CPF, e-mail, telefone e saldo; não marque esse conjunto se o consumidor não precisar desses dados.']},{title:'2. Crie e armazene a chave',items:['Nomeie a integração para identificar proprietário e finalidade.','Copie fz_live_ apenas no momento da criação; o hash fica armazenado e a chave completa não volta a ser exibida.','Guarde no cofre de segredos ou variável FIDELIZEI_API_KEY do servidor consumidor, nunca no front-end.']},{title:'3. Faça a primeira chamada',items:['Use a URL base https://api.fidelizaplus.com.br/public/v1 e Authorization: Bearer.','Consulte somente os endpoints liberados para a chave; 403 indica escopo ausente ou plano sem acesso.','Use limit/offset com no máximo 500 resultados e respeite o limite de 120 chamadas por minuto.']}],validation:['Endpoint autorizado retorna 200 e paginação','Endpoint sem escopo retorna 403','Último uso aparece no painel da chave','A chave pode ser revogada e deixa de autenticar'],troubleshooting:['401: reveja prefixo, Bearer, expiração e estado ativo.','403: confira escopo e plano; não solicite escopo mais amplo sem necessidade.','429: reduza tráfego e aplique backoff exponencial.','Integração exige campo não disponível: documente requisito; não coloque a chave em um site público para contornar.']},

];

function GuideArticle({guide}:{guide:Guide}){return <article className="blog-article guide-article"><a href="/blog">← Voltar para a Central de Ajuda</a><div className="guide-meta"><span className="site-eyebrow">{guide.tag.toUpperCase()}</span><span><Users/> {guide.audience}</span><span><Clock3/> {guide.duration}</span></div><h1>{guide.title}</h1><p>{guide.summary}</p><div className="guide-path"><b>Onde fazer no Fidelizei</b><code>{guide.path}</code></div><section className="guide-prerequisites"><h2>Antes de começar</h2><ul>{guide.prerequisites.map(item=><li key={item}><Check/>{item}</li>)}</ul></section>{guide.sections.map(section=><section className="guide-section" key={section.title}><h2>{section.title}</h2><ol>{section.items.map(item=><li key={item}>{item}</li>)}</ol></section>)}<div className="guide-two-columns"><section><h2>Como saber que funcionou</h2><ul>{guide.validation.map(item=><li key={item}><Check/>{item}</li>)}</ul></section><section className="guide-troubleshooting"><h2>Se algo der errado</h2><ul>{guide.troubleshooting.map(item=><li key={item}>{item}</li>)}</ul></section></div>{guide.links&&<section className="guide-links"><h2>Documentação oficial</h2>{guide.links.map(link=><a href={link.url} target="_blank" rel="noreferrer" key={link.url}>{link.label}<ExternalLink/></a>)}</section>}<aside><b>Pronto para configurar?</b><p>Entre no portal da sua empresa e siga este roteiro. Faça a homologação antes de usar dados reais.</p><div><a className="site-button" href="/login">Acessar o portal</a><a className="site-button ghost" href="/planos">Consultar recursos</a></div></aside></article>}

export function PublicBlog(){const slug=location.pathname.split('/')[2],selected=guides.find(guide=>guide.slug===slug),[query,setQuery]=useState(''),[tag,setTag]=useState('Todos');usePublicMeta(selected?.title||'Central de ajuda Fidelizei',selected?.summary||'Guias práticos para configurar fidelidade, integrar ERPs, campanhas e segurança no Fidelizei.',selected?`/blog/${selected.slug}`:'/blog');if(selected)return <Frame><main><GuideArticle guide={selected}/></main></Frame>;const tags=['Todos',...new Set(guides.map(guide=>guide.tag))],normalized=query.toLocaleLowerCase('pt-BR'),filtered=guides.filter(guide=>(tag==='Todos'||guide.tag===tag)&&`${guide.title} ${guide.summary} ${guide.path}`.toLocaleLowerCase('pt-BR').includes(normalized));return <Frame><main><section className="blog-hero"><span className="site-eyebrow"><BookOpen/> CENTRAL DE AJUDA FIDELIZEI</span><h1>Da configuração ao resultado, sem adivinhação.</h1><p>Guias operacionais com o caminho exato no sistema, pré-requisitos, validações e solução de problemas.</p><div className="help-highlights"><span><Check/> Passo a passo dentro do portal</span><span><Check/> Homologação de integrações</span><span><Check/> Diagnóstico de falhas</span></div></section><section className="help-tools"><label><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar Bling, API, campanhas, cobrança…"/></label><div>{tags.map(item=><button className={tag===item?'active':''} onClick={()=>setTag(item)} key={item}>{item}</button>)}</div></section><section className="blog-grid help-grid">{filtered.map(guide=><a href={`/blog/${guide.slug}`} key={guide.slug}><span>{guide.tag}</span><h2>{guide.title}</h2><p>{guide.summary}</p><small><Clock3/>{guide.duration} · {guide.audience}</small><code>{guide.path}</code><b>Abrir documentação <ChevronRight/></b></a>)}{!filtered.length&&<div className="help-empty"><BookOpen/><h2>Nenhum guia encontrado</h2><p>Tente outro termo ou selecione “Todos”.</p></div>}</section></main></Frame>}

export function PublicFaq(){const[query,setQuery]=useState('');usePublicMeta('Perguntas frequentes sobre fidelidade','Respostas práticas sobre planos, clientes, pontos, recompensas, ofertas, integrações, API e segurança do Fidelizei.','/faq');const needle=query.trim().toLocaleLowerCase('pt-BR'),visible=supportFaq.map(group=>({...group,items:group.items.filter(item=>!needle||`${group.title} ${item.q} ${item.a}`.toLocaleLowerCase('pt-BR').includes(needle))})).filter(group=>group.items.length);return <Frame><main><section className="public-page-hero faq-page-hero"><span className="site-eyebrow"><BookOpen/> CENTRAL DE AJUDA FIDELIZEI</span><h1>Perguntas frequentes sobre a plataforma.</h1><p>Respostas sobre configuração, vendas, pontos, recompensas, acesso do cliente, integrações e segurança — com os limites atuais do produto explicados com clareza.</p><div className="faq-hub-search"><Search/><input aria-label="Buscar nas perguntas frequentes" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar: pontos, pedido, API, senha…"/></div></section><section className="site-section faq-hub">{visible.map((group,index)=><section key={group.title} aria-labelledby={`faq-group-${index}`}><h2 id={`faq-group-${index}`}>{group.title}</h2>{group.items.map(item=><details key={item.q}><summary>{item.q}</summary><p>{item.a}</p></details>)}</section>)}{!visible.length&&<div className="faq-empty"><Search/><h2>Nenhuma resposta encontrada</h2><p>Tente outro termo ou <button type="button" onClick={()=>setQuery('')}>limpe a busca</button>.</p></div>}</section><section className="site-cta"><div><h2>Não encontrou o que precisava?</h2><p>Consulte os tutoriais por tarefa ou acesse o suporte da sua empresa.</p></div><a className="site-button" href="/blog">Ver guias e tutoriais <ArrowRight/></a></section></main></Frame>}

function usePublicMeta(title:string,description:string,path:string){useEffect(()=>{const fullTitle=`${title} | Fidelizei`,url=new URL(path,'https://fidelizaplus.com.br').href;document.title=fullTitle;const setMeta=(selector:string,attribute:'name'|'property',key:string,value:string)=>{let element=document.querySelector(selector) as HTMLMetaElement|null;if(!element){element=document.createElement('meta');element.setAttribute(attribute,key);document.head.appendChild(element)}element.content=value};setMeta('meta[name="description"]','name','description',description);setMeta('meta[property="og:type"]','property','og:type',path.startsWith('/blog/')?'article':'website');setMeta('meta[property="og:site_name"]','property','og:site_name','Fidelizei');setMeta('meta[property="og:locale"]','property','og:locale','pt_BR');setMeta('meta[property="og:title"]','property','og:title',fullTitle);setMeta('meta[property="og:description"]','property','og:description',description);setMeta('meta[property="og:url"]','property','og:url',url);setMeta('meta[property="og:image"]','property','og:image','https://fidelizaplus.com.br/fidelizei-social.png');setMeta('meta[property="og:image:alt"]','property','og:image:alt','Fidelizei — plataforma de fidelidade para empresas');setMeta('meta[name="twitter:card"]','name','twitter:card','summary_large_image');setMeta('meta[name="twitter:title"]','name','twitter:title',fullTitle);setMeta('meta[name="twitter:description"]','name','twitter:description',description);setMeta('meta[name="twitter:image"]','name','twitter:image','https://fidelizaplus.com.br/fidelizei-social.png');const noIndex=['/admin','/login','/cliente','/reset-password','/acesso'].some(route=>path===route||path.startsWith(route+'/'));setMeta('meta[name="robots"]','name','robots',noIndex?'noindex,nofollow':'index,follow,max-image-preview:large');let canonical=document.querySelector('link[rel="canonical"]') as HTMLLinkElement|null;if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical)}canonical.href=url;const graph:Record<string,unknown>[]=[{'@type':'Organization','@id':'https://fidelizaplus.com.br/#organization','name':'Fidelizei','url':'https://fidelizaplus.com.br/','logo':'https://fidelizaplus.com.br/fidelizei.svg','email':'contato@fidelizaplus.com.br'},{'@type':'WebSite','@id':'https://fidelizaplus.com.br/#website','url':'https://fidelizaplus.com.br/','name':'Fidelizei','inLanguage':'pt-BR','publisher':{'@id':'https://fidelizaplus.com.br/#organization'}},{'@type':'SoftwareApplication','@id':'https://fidelizaplus.com.br/#software','name':'Fidelizei','applicationCategory':'BusinessApplication','operatingSystem':'Web','url':'https://fidelizaplus.com.br/','description':'Plataforma de fidelidade para empresas que conecta ERP, clientes, vendas, pontos, recompensas e relacionamento.','publisher':{'@id':'https://fidelizaplus.com.br/#organization'}}];if(path==='/'){graph.push({'@type':'FAQPage','mainEntity':[{'@type':'Question','name':'Como os pontos são calculados?','acceptedAnswer':{'@type':'Answer','text':'A empresa configura suas regras. Em vendas identificadas e elegíveis, o Fidelizei calcula os pontos e registra a movimentação no extrato do cliente.'}},{'@type':'Question','name':'O que acontece quando um pedido é cancelado?','acceptedAnswer':{'@type':'Answer','text':'Na integração Bling, pedidos cancelados ou excluídos são conciliados e os pontos correspondentes podem ser estornados automaticamente.'}},{'@type':'Question','name':'O cliente precisa instalar um aplicativo?','acceptedAnswer':{'@type':'Answer','text':'O acesso funciona como aplicativo web responsivo e pode ser instalado no celular quando o navegador oferecer essa opção.'}},{'@type':'Question','name':'Outros ERPs já estão disponíveis?','acceptedAnswer':{'@type':'Answer','text':'O conector Bling está disponível. Outros provedores só serão publicados como disponíveis após implementação e homologação.'}}]})}if(path==='/faq')graph.push({'@type':'FAQPage','mainEntity':supportFaq.flatMap(group=>group.items.map(item=>({'@type':'Question','name':item.q,'acceptedAnswer':{'@type':'Answer','text':item.a}})))});if(path.startsWith('/blog/'))graph.push({'@type':'Article','headline':title,'description':description,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'Fidelizei'},'publisher':{'@id':'https://fidelizaplus.com.br/#organization'},'inLanguage':'pt-BR'});const scriptId='fidelizei-public-schema';let schema=document.getElementById(scriptId) as HTMLScriptElement|null;if(!schema){schema=document.createElement('script');schema.id=scriptId;schema.type='application/ld+json';document.head.appendChild(schema)}schema.textContent=JSON.stringify({'@context':'https://schema.org','@graph':graph});return()=>{}},[title,description,path])}
function PublicPage({eyebrow,title,description,children,path}:{eyebrow:string;title:string;description:string;children:React.ReactNode;path:string}){usePublicMeta(title,description,path);return <Frame><main><section className="public-page-hero"><span className="site-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p><div className="site-actions"><a className="site-button" href="/planos">Começar 7 dias grátis <ArrowRight/></a><a className="site-button ghost" href="/contato">Falar com o Fidelizei</a></div></section>{children}</main></Frame>}

export function PublicProduct(){return <PublicPage eyebrow="PRODUTO" title="Uma plataforma para operar fidelidade de ponta a ponta." description="Centralize clientes, vendas, pontos, níveis, recompensas, ofertas e relacionamento, com recursos liberados conforme o plano contratado." path="/produto"><section className="site-section product-modules"><h2>Do cadastro ao benefício utilizado.</h2><div className="module-grid"><article><Users/><b>CRM e níveis</b><p>Histórico por cliente, segmentação e benefícios compatíveis com o nível atual.</p></article><article><ReceiptText/><b>Vendas e pontos</b><p>Registro rastreável de compras, créditos, ajustes, estornos e saldo.</p></article><article><Gift/><b>Recompensas</b><p>Cupons de uso único, validade configurável e elegibilidade por nível.</p></article><article><ShoppingBag/><b>Ofertas exclusivas</b><p>Produtos com preço exclusivo, reserva no aplicativo e pagamento direto à loja.</p></article><article><Megaphone/><b>Campanhas</b><p>Comunicação e experimentos somente nos planos e canais habilitados.</p></article><article><BarChart3/><b>Gestão</b><p>Visões operacionais, gerenciais e avançadas conforme a assinatura.</p></article></div></section><section className="site-section workflow-panel"><span className="site-eyebrow">FLUXO OPERACIONAL</span><h2>Uma cadeia de informação, não telas isoladas.</h2><ol><li><b>1</b><span>O cliente entra no programa da empresa e recebe sua identificação.</span></li><li><b>2</b><span>Uma venda identificada entra pelo Bling ou pelo fluxo operacional autorizado.</span></li><li><b>3</b><span>As regras vigentes calculam os pontos e atualizam nível e extrato.</span></li><li><b>4</b><span>O cliente acompanha saldo, ofertas e benefícios no ambiente personalizado.</span></li><li><b>5</b><span>A loja valida cupons, atende solicitações e acompanha resultados.</span></li></ol></section></PublicPage>}

